            box = Gtk.Box(orientation=Gtk.Orientation.VERTICAL, margin=20)
            box.pack_start(self.new_proj_rev, True, True, 0)
            self.np_dialog.add(box)
        self.toggle_new_project(True)
        self.np_dialog.show_all()

